Criar um **jogo da cobra (Snake)** em **C**, com **movimentação suave** e **imagens para animar o nível**, é um projeto legal e bem desafiador! Em C, você não tem uma engine gráfica embutida, então vamos usar uma biblioteca gráfica como **SDL2 (Simple DirectMedia Layer 2)**, que é poderosa, portável e ideal para esse tipo de projeto.

Abaixo, te mostro:

1. **Como configurar o ambiente com SDL2**
2. **Estrutura básica do jogo da cobra**
3. **Como fazer a movimentação suave (não em bloco)**
4. **Como carregar e exibir imagens**
5. **Como animar a cobra e o cenário**

---

### ✅ 1. Instalar e Configurar o SDL2

#### No Linux (Ubuntu/Debian):
```bash
sudo apt-get install libsdl2-dev libsdl2-image-dev
```

#### No Windows:
- Baixe o SDL2-devel do site: https://www.libsdl.org/download-2.0.php
- Extraia e configure com MinGW ou Visual Studio.
- Use `gcc` com flags apropriadas.

#### Compilar (Linux):
```bash
gcc snake.c -o snake -lSDL2 -lSDL2_image
```

---

### ✅ 2. Estrutura do Jogo

Vamos usar:

- `SDL_Texture` para carregar imagens
- `SDL_Rect` para posição e tamanho
- Movimentação suave com `float` para coordenadas
- Lógica de corpo da cobra em uma lista circular ou array

---

### ✅ 3. Código Base do Jogo da Cobra com Imagens e Animação Suave

```c
// snake.c
#include <SDL2/SDL.h>
#include <SDL2/IMG/SDL_image.h>
#include <stdio.h>
#include <stdlib.h>

#define SCREEN_WIDTH 800
#define SCREEN_HEIGHT 600
#define TILE_SIZE 32
#define MAX_SEGMENTS 1000
#define SNAKE_SPEED 100.0f  // pixels per second

// Estrutura para cada segmento da cobra
typedef struct {
    float x, y;
} Segment;

// Função para carregar texturas
SDL_Texture* loadTexture(const char* path, SDL_Renderer* renderer) {
    SDL_Texture* newTexture = NULL;
    SDL_Surface* loadedSurface = IMG_Load(path);
    if (!loadedSurface) {
        printf("Erro ao carregar imagem %s! SDL_image Error: %s\n", path, IMG_GetError());
        return NULL;
    }
    newTexture = SDL_CreateTextureFromSurface(renderer, loadedSurface);
    SDL_FreeSurface(loadedSurface);
    return newTexture;
}

int main(int argc, char* argv[]) {
    // Inicializa SDL
    if (SDL_Init(SDL_INIT_VIDEO) < 0) {
        printf("Erro ao inicializar SDL: %s\n", SDL_GetError());
        return 1;
    }

    // Inicializa SDL_image com suporte a PNG
    int imgFlags = IMG_INIT_PNG;
    if (!(IMG_Init(imgFlags) & imgFlags)) {
        printf("Erro ao inicializar SDL_image: %s\n", IMG_GetError());
        return 1;
    }

    // Cria janela e renderer
    SDL_Window* window = SDL_CreateWindow("Jogo da Cobra", SDL_WINDOWPOS_CENTERED, SDL_WINDOWPOS_CENTERED,
                                          SCREEN_WIDTH, SCREEN_HEIGHT, SDL_WINDOW_SHOWN);
    SDL_Renderer* renderer = SDL_CreateRenderer(window, -1, SDL_RENDERER_ACCELERATED);

    // Carrega texturas
    SDL_Texture* headTex = loadTexture("assets/head.png", renderer);
    SDL_Texture* bodyTex = loadTexture("assets/body.png", renderer);
    SDL_Texture* foodTex = loadTexture("assets/food.png", renderer);
    SDL_Texture* bgTex = loadTexture("assets/background.png", renderer);

    if (!headTex || !bodyTex || !foodTex || !bgTex) {
        printf("Erro ao carregar uma das texturas!\n");
        return 1;
    }

    // Estado do jogo
    Segment snake[MAX_SEGMENTS];
    int numSegments = 3;
    float snakeX = SCREEN_WIDTH / 2;
    float snakeY = SCREEN_HEIGHT / 2;
    float velocityX = SNAKE_SPEED;
    float velocityY = 0;
    int direction = 0; // 0: direita, 1: cima, 2: esquerda, 3: baixo
    int nextDirection = 0;

    // Posição da comida
    float foodX = 200, foodY = 200;

    // Inicializa segmentos da cobra
    for (int i = 0; i < numSegments; i++) {
        snake[i].x = snakeX - i * 10;
        snake[i].y = snakeY;
    }

    // Tempo para movimentação suave
    Uint64 lastTime = SDL_GetTicks64();
    float accumulator = 0.0f;

    // Loop principal
    int running = 1;
    SDL_Event e;

    while (running) {
        Uint64 currentTime = SDL_GetTicks64();
        float deltaTime = (currentTime - lastTime) / 1000.0f; // em segundos
        lastTime = currentTime;
        accumulator += deltaTime;

        // Processa eventos
        while (SDL_PollEvent(&e)) {
            if (e.type == SDL_QUIT) {
                running = 0;
            }
        }

        // Input do teclado
        const Uint8* keys = SDL_GetKeyboardState(NULL);
        if (keys[SDL_SCANCODE_UP] && direction != 3) nextDirection = 1;
        if (keys[SDL_SCANCODE_DOWN] && direction != 1) nextDirection = 3;
        if (keys[SDL_SCANCODE_LEFT] && direction != 0) nextDirection = 2;
        if (keys[SDL_SCANCODE_RIGHT] && direction != 2) nextDirection = 0;

        // Atualiza a direção
        direction = nextDirection;

        // Atualiza a posição com integração fixa para suavidade
        const float fixedTimeStep = 1.0f / 60.0f; // 60 FPS
        while (accumulator >= fixedTimeStep) {
            // Move a cabeça
            if (direction == 0) snakeX += SNAKE_SPEED * fixedTimeStep;
            if (direction == 1) snakeY -= SNAKE_SPEED * fixedTimeStep;
            if (direction == 2) snakeX -= SNAKE_SPEED * fixedTimeStep;
            if (direction == 3) snakeY += SNAKE_SPEED * fixedTimeStep;

            accumulator -= fixedTimeStep;

            // Atualiza corpo: empurra cada segmento para a frente
            for (int i = numSegments - 1; i > 0; i--) {
                snake[i] = snake[i - 1];
            }
            snake[0].x = snakeX;
            snake[0].y = snakeY;
        }

        // Verifica colisão com comida
        if (fabs(snake[0].x - foodX) < 15 && fabs(snake[0].y - foodY) < 15) {
            foodX = (rand() % (SCREEN_WIDTH / TILE_SIZE)) * TILE_SIZE;
            foodY = (rand() % (SCREEN_HEIGHT / TILE_SIZE)) * TILE_SIZE;
            if (numSegments < MAX_SEGMENTS - 1) {
                numSegments++;
                // Novo segmento na mesma posição do último
                snake[numSegments - 1] = snake[numSegments - 2];
            }
        }

        // Desenha
        SDL_SetRenderDrawColor(renderer, 0, 0, 0, 255);
        SDL_RenderClear(renderer);

        // Desenha fundo
        SDL_Rect bgRect = {0, 0, SCREEN_WIDTH, SCREEN_HEIGHT};
        SDL_RenderCopy(renderer, bgTex, NULL, &bgRect);

        // Desenha cada segmento
        for (int i = 0; i < numSegments; i++) {
            SDL_Rect segmentRect = {
                (int)snake[i].x, (int)snake[i].y, TILE_SIZE, TILE_SIZE
            };

            if (i == 0) {
                // Cabeça: pode rotacionar se quiser, aqui só exibe
                SDL_RenderCopy(renderer, headTex, NULL, &segmentRect);
            } else {
                SDL_RenderCopy(renderer, bodyTex, NULL, &segmentRect);
            }
        }

        // Desenha comida
        SDL_Rect foodRect = {(int)foodX, (int)foodY, TILE_SIZE, TILE_SIZE};
        SDL_RenderCopy(renderer, foodTex, NULL, &foodRect);

        SDL_RenderPresent(renderer);
        SDL_Delay(16); // ~60 FPS
    }

    // Limpeza
    SDL_DestroyTexture(headTex);
    SDL_DestroyTexture(bodyTex);
    SDL_DestroyTexture(foodTex);
    SDL_DestroyTexture(bgTex);
    SDL_DestroyRenderer(renderer);
    SDL_DestroyWindow(window);
    IMG_Quit();
    SDL_Quit();

    return 0;
}
```

---

### ✅ 4. Estrutura de Arquivos

Crie uma pasta `assets/` com as imagens:

```
assets/
    head.png     (cabeça da cobra)
    body.png     (corpo da cobra)
    food.png     (comida)
    background.png (fundo do nível)
```

> Você pode fazer essas imagens em 32x32 pixels com editor como GIMP, Aseprite, ou usar sprites gratuitos.

---

### ✅ 5. Como Melhorar: Animação Suave e Realista

- **Interpolação de movimento**: Use `float` para posição e desenhe com `(int)round(pos)`
- **Efeitos de animação**: Adicione uma variável de fase para piscar comida ou animar fundo
- **Rotação da cabeça**: Use `SDL_RenderCopyEx` para rotacionar a cabeça conforme a direção
- **Partículas e sons**: Use `SDL_mixer` para sons ao comer

---

### ✅ 6. Dicas Finais

- Use `git` para versionar seu projeto.
- Teste em máquinas diferentes.
- Para melhor desempenho, use `SDL_HINT_RENDER_SCALE_QUALITY`, "1".
- Considere usar um loop de jogo com `fixed timestep` para física consistente.

---

### ✅ Exemplo de Makefile (opcional)

```makefile
CC = gcc
CFLAGS = -Wall -Wextra
LIBS = -lSDL2 -lSDL2_image

snake: snake.c
	$(CC) $(CFLAGS) -o snake snake.c $(LIBS)

clean:
	rm -f snake

run: snake
	./snake
```

